const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class TruncatedPercentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function isUnreserved(ch) {
  return (
    (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') ||
    (ch >= '0' && ch <= '9') ||
    ch === '-' ||
    ch === '.' ||
    ch === '_' ||
    ch === '~'
  )
}

function lowerAscii(s) {
  let out = ''
  for (const ch of s) {
    out += ch >= 'A' && ch <= 'Z' ? ch.toLowerCase() : ch
  }
  return out
}

/**
 * Split a URI reference into its five generic components. Absent components
 * are `null`; present-but-empty components are `''`. The authority is kept
 * as a single string here; splitAuthority breaks it into userinfo/host/port.
 */
export function parseReference(s) {
  let scheme = null
  let rest = s
  const colonIdx = s.indexOf(':')
  if (colonIdx !== -1) {
    const prefix = s.slice(0, colonIdx)
    if (!/[/?#]/.test(prefix)) {
      scheme = prefix
      rest = s.slice(colonIdx + 1)
    }
  }

  let authority = null
  if (rest.startsWith('//')) {
    let idx = rest.length
    for (let i = 2; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        idx = i
        break
      }
    }
    authority = rest.slice(2, idx)
    rest = rest.slice(idx)
  }

  let pathEnd = rest.length
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === '?' || c === '#') {
      pathEnd = i
      break
    }
  }
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query = null
  if (rest.startsWith('?')) {
    let idx = rest.length
    for (let i = 1; i < rest.length; i++) {
      if (rest[i] === '#') {
        idx = i
        break
      }
    }
    query = rest.slice(1, idx)
    rest = rest.slice(idx)
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
