/** Split an authority string into userinfo/host/port, each null when absent. */
export function splitAuthority(authority) {
  let userinfo = null
  let rest = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    rest = authority.slice(atIdx + 1)
  }
  const bracketIdx = rest.lastIndexOf(']')
  const searchFrom = bracketIdx !== -1 ? bracketIdx : 0
  const colonIdx = rest.indexOf(':', searchFrom)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }
  return { userinfo, host, port }
}

function joinAuthority(userinfo, host, port) {
  let s = ''
  if (userinfo !== null) s += userinfo + '@'
  s += host
  if (port !== null) s += ':' + port
  return s
}

/** Uppercase %XX triplets and decode the ones that are unreserved characters. */
function normalizePercent(str, component) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (hex.length < 2 || !/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new TruncatedPercentError(component)
